inline bool loadCompressedInto(TableBank& bank) {
    bank.w4x4 = defaultWeights4x4();
    bank.w5x5 = defaultWeights5x5();
    bank.checksum = kPrecomputedChecksum;
    bank.c4_ud.resize(367736);
    if (!decompressRLE(kC4_UD_rle, sizeof(kC4_UD_rle), bank.c4_ud.data(), 367736)) return false;
    bank.c4_s2.resize(450450);
    if (!decompressRLE(kC4_S2_rle, sizeof(kC4_S2_rle), bank.c4_s2.data(), 450450)) return false;
    bank.c4_s3.resize(171500);
    if (!decompressRLE(kC4_S3_rle, sizeof(kC4_S3_rle), bank.c4_s3.data(), 171500)) return false;
    bank.t5_ud.resize(367736);
    if (!decompressRLE(kT5_UD_rle, sizeof(kT5_UD_rle), bank.t5_ud.data(), 367736)) return false;
    bank.t5_s2.resize(450450);
    if (!decompressRLE(kT5_S2_rle, sizeof(kT5_S2_rle), bank.t5_s2.data(), 450450)) return false;
    bank.t5_s3.resize(171500);
    if (!decompressRLE(kT5_S3_rle, sizeof(kT5_S3_rle), bank.t5_s3.data(), 171500)) return false;
    bank.x5_ud.resize(367736);
    if (!decompressRLE(kX5_UD_rle, sizeof(kX5_UD_rle), bank.x5_ud.data(), 367736)) return false;
    bank.x5_s2.resize(450450);
    if (!decompressRLE(kX5_S2_rle, sizeof(kX5_S2_rle), bank.x5_s2.data(), 450450)) return false;
    bank.x5_s3.resize(171500);
    if (!decompressRLE(kX5_S3_rle, sizeof(kX5_S3_rle), bank.x5_s3.data(), 171500)) return false;
    bank.ready = true;
    return true;
}

